def same_after_backspaces(first, second):
    def final(s):
        stack = []
        for ch in s:
            if ch == "#":
                if stack:
                    stack.pop()
            else:
                stack.append(ch)
        return stack

    return final(first) == final(second)

def same_after_backspaces(first, second):
    i, j = len(first) - 1, len(second) - 1
    skip_a = skip_b = 0
    while i >= 0 or j >= 0:
        while i >= 0:
            if first[i] == "#":
                skip_a += 1
                i -= 1
            elif skip_a > 0:
                skip_a -= 1
                i -= 1
            else:
                break
        while j >= 0:
            if second[j] == "#":
                skip_b += 1
                j -= 1
            elif skip_b > 0:
                skip_b -= 1
                j -= 1
            else:
                break
        if i >= 0 and j >= 0:
            if first[i] != second[j]:
                return False
        elif i >= 0 or j >= 0:
            return False
        i -= 1
        j -= 1
    return True

function sameAfterBackspaces(first, second) {
  const final = (s) => {
    const stack = [];
    for (const ch of s) {
      if (ch === "#") stack.pop();
      else stack.push(ch);
    }
    return stack.join("");
  };
  return final(first) === final(second);
}

class Solution {
    private String finalText(String s) {
        StringBuilder stack = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (ch == '#') { if (stack.length() > 0) stack.deleteCharAt(stack.length() - 1); }
            else stack.append(ch);
        }
        return stack.toString();
    }

    public boolean sameAfterBackspaces(String first, String second) {
        return finalText(first).equals(finalText(second));
    }
}

static string final_text(const string& s) {
    string stack;
    for (char ch : s) {
        if (ch == '#') { if (!stack.empty()) stack.pop_back(); }
        else stack.push_back(ch);
    }
    return stack;
}
bool same_after_backspaces(string first, string second) {
    return final_text(first) == final_text(second);
}

def is_balanced(text):
    previous = None
    while previous != text:
        previous = text
        text = text.replace("()", "").replace("[]", "").replace("{}", "")
    return text == ""

def is_balanced(text):
    match = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif not stack or stack.pop() != match[ch]:
            return False
    return not stack

function isBalanced(text) {
  const match = { ")": "(", "]": "[", "}": "{" };
  const stack = [];
  for (const ch of text) {
    if (ch === "(" || ch === "[" || ch === "{") stack.push(ch);
    else if (stack.length === 0 || stack.pop() !== match[ch]) return false;
  }
  return stack.length === 0;
}

class Solution {
    public boolean isBalanced(String text) {
        char[] stack = new char[text.length()];
        int top = 0;
        for (char ch : text.toCharArray()) {
            if (ch == '(' || ch == '[' || ch == '{') {
                stack[top++] = ch;
            } else {
                if (top == 0) return false;
                char open = stack[--top];
                if ((ch == ')' && open != '(') || (ch == ']' && open != '[') || (ch == '}' && open != '{')) return false;
            }
        }
        return top == 0;
    }
}

bool is_balanced(string text) {
    string stack;
    for (char ch : text) {
        if (ch == '(' || ch == '[' || ch == '{') {
            stack.push_back(ch);
        } else {
            if (stack.empty()) return false;
            char open = stack.back();
            stack.pop_back();
            if ((ch == ')' && open != '(') || (ch == ']' && open != '[') || (ch == '}' && open != '{')) return false;
        }
    }
    return stack.empty();
}

def total_score(ops):
    record = []
    for op in ops.split(" "):
        if op == "+":
            record.append(sum(record[-2:]))
        elif op == "D":
            record.append(2 * record[-1])
        elif op == "C":
            record = record[:-1]
        else:
            record = record + [int(op)]
    return sum(record)

def total_score(ops):
    stack = []
    total = 0
    for op in ops.split(" "):
        if op == "C":
            total -= stack.pop()
            continue
        if op == "+":
            value = stack[-1] + stack[-2]
        elif op == "D":
            value = 2 * stack[-1]
        else:
            value = int(op)
        stack.append(value)
        total += value
    return total

function totalScore(ops) {
  const stack = [];
  let total = 0;
  for (const op of ops.split(" ")) {
    if (op === "C") { total -= stack.pop(); continue; }
    let value;
    if (op === "+") value = stack[stack.length - 1] + stack[stack.length - 2];
    else if (op === "D") value = 2 * stack[stack.length - 1];
    else value = parseInt(op, 10);
    stack.push(value);
    total += value;
  }
  return total;
}

class Solution {
    public int totalScore(String ops) {
        Deque<Integer> stack = new ArrayDeque<>();
        int total = 0;
        for (String op : ops.split(" ")) {
            if (op.equals("C")) { total -= stack.pop(); continue; }
            int value;
            if (op.equals("+")) {
                int top = stack.pop();
                int second = stack.peek();
                stack.push(top);
                value = top + second;
            } else if (op.equals("D")) value = 2 * stack.peek();
            else value = Integer.parseInt(op);
            stack.push(value);
            total += value;
        }
        return total;
    }
}

int total_score(string ops) {
    vector<int> stack;
    int total = 0;
    istringstream in(ops);
    string op;
    while (in >> op) {
        if (op == "C") { total -= stack.back(); stack.pop_back(); continue; }
        int value;
        if (op == "+") value = stack[stack.size() - 1] + stack[stack.size() - 2];
        else if (op == "D") value = 2 * stack.back();
        else value = stoi(op);
        stack.push_back(value);
        total += value;
    }
    return total;
}

