def build_tree(preorder, inorder):
    position = {value: i for i, value in enumerate(inorder)}
    next_index = [0]

    def build(lo, hi):
        if lo > hi:
            return None
        value = preorder[next_index[0]]
        next_index[0] += 1
        node = TreeNode(value)
        mid = position[value]
        node.left = build(lo, mid - 1)
        node.right = build(mid + 1, hi)
        return node

    return build(0, len(inorder) - 1)

function buildTree(preorder, inorder) {
  const position = new Map();
  inorder.forEach((v, i) => position.set(v, i));
  let next = 0;
  const build = (lo, hi) => {
    if (lo > hi) return null;
    const value = preorder[next++];
    const node = new TreeNode(value, null, null);
    const mid = position.get(value);
    node.left = build(lo, mid - 1);
    node.right = build(mid + 1, hi);
    return node;
  };
  return build(0, inorder.length - 1);
}

class Solution {
    private Map<Integer, Integer> position = new HashMap<>();
    private int next;

    private TreeNode build(int[] preorder, int lo, int hi) {
        if (lo > hi) return null;
        int value = preorder[next++];
        TreeNode node = new TreeNode(value);
        int mid = position.get(value);
        node.left = build(preorder, lo, mid - 1);
        node.right = build(preorder, mid + 1, hi);
        return node;
    }

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        position = new HashMap<>();
        next = 0;
        for (int i = 0; i < inorder.length; i++) position.put(inorder[i], i);
        return build(preorder, 0, inorder.length - 1);
    }
}

static TreeNode* rebuild(vector<int>& preorder, unordered_map<int, int>& position, int& next, int lo, int hi) {
    if (lo > hi) return nullptr;
    int value = preorder[next++];
    TreeNode* node = new TreeNode(value);
    int mid = position[value];
    node->left = rebuild(preorder, position, next, lo, mid - 1);
    node->right = rebuild(preorder, position, next, mid + 1, hi);
    return node;
}
TreeNode* build_tree(vector<int>& preorder, vector<int>& inorder) {
    unordered_map<int, int> position;
    for (int i = 0; i < (int) inorder.size(); i++) position[inorder[i]] = i;
    int next = 0;
    return rebuild(preorder, position, next, 0, (int) inorder.size() - 1);
}

def can_finish(n, prerequisites):
    remaining = set(range(n))
    edges = [tuple(e) for e in prerequisites]
    progress = True
    while progress:
        progress = False
        for course in list(remaining):
            if not any(a == course and b in remaining for a, b in edges):
                remaining.remove(course)
                progress = True
    return not remaining

def can_finish(n, prerequisites):
    indegree = [0] * n
    needs = [[] for _ in range(n)]
    for a, b in prerequisites:
        needs[b].append(a)
        indegree[a] += 1
    queue = [c for c in range(n) if indegree[c] == 0]
    taken = 0
    for c in queue:
        taken += 1
        for x in needs[c]:
            indegree[x] -= 1
            if indegree[x] == 0:
                queue.append(x)
    return taken == n

function canFinish(n, prerequisites) {
  const indegree = new Array(n).fill(0);
  const needs = Array.from({ length: n }, () => []);
  for (const [a, b] of prerequisites) { needs[b].push(a); indegree[a]++; }
  const queue = [];
  for (let c = 0; c < n; c++) if (indegree[c] === 0) queue.push(c);
  let taken = 0;
  for (let head = 0; head < queue.length; head++) {
    taken++;
    for (const x of needs[queue[head]]) if (--indegree[x] === 0) queue.push(x);
  }
  return taken === n;
}

class Solution {
    public boolean canFinish(int n, int[][] prerequisites) {
        int[] indegree = new int[n];
        List<List<Integer>> needs = new ArrayList<>();
        for (int i = 0; i < n; i++) needs.add(new ArrayList<>());
        for (int[] p : prerequisites) { needs.get(p[1]).add(p[0]); indegree[p[0]]++; }
        Deque<Integer> queue = new ArrayDeque<>();
        for (int c = 0; c < n; c++) if (indegree[c] == 0) queue.add(c);
        int taken = 0;
        while (!queue.isEmpty()) {
            int c = queue.poll();
            taken++;
            for (int x : needs.get(c)) if (--indegree[x] == 0) queue.add(x);
        }
        return taken == n;
    }
}

bool can_finish(int n, vector<vector<int>>& prerequisites) {
    vector<int> indegree(n, 0);
    vector<vector<int>> needs(n);
    for (auto& p : prerequisites) { needs[p[1]].push_back(p[0]); indegree[p[0]]++; }
    queue<int> q;
    for (int c = 0; c < n; c++) if (indegree[c] == 0) q.push(c);
    int taken = 0;
    while (!q.empty()) {
        int c = q.front();
        q.pop();
        taken++;
        for (int x : needs[c]) if (--indegree[x] == 0) q.push(x);
    }
    return taken == n;
}

def min_candies(ratings):
    n = len(ratings)
    candies = [1] * n
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if i > 0 and ratings[i] > ratings[i - 1] and candies[i] <= candies[i - 1]:
                candies[i] = candies[i - 1] + 1
                changed = True
            if i < n - 1 and ratings[i] > ratings[i + 1] and candies[i] <= candies[i + 1]:
                candies[i] = candies[i + 1] + 1
                changed = True
    return sum(candies)

def min_candies(ratings):
    n = len(ratings)
    candies = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)
    return sum(candies)

function minCandies(ratings) {
  const n = ratings.length;
  const candies = new Array(n).fill(1);
  for (let i = 1; i < n; i++) if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
  for (let i = n - 2; i >= 0; i--) if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);
  return candies.reduce((x, y) => x + y, 0);
}

class Solution {
    public int minCandies(int[] ratings) {
        int n = ratings.length;
        int[] candies = new int[n];
        Arrays.fill(candies, 1);
        for (int i = 1; i < n; i++) if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--) if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);
        long total = 0;
        for (int c : candies) total += c;
        return (int) total;
    }
}

