def cheapest_with_stops(n, flights, src, dst, k):
    best = [None]

    def go(city, cost, flights_used):
        if best[0] is not None and cost >= best[0]:
            return
        if city == dst:
            best[0] = cost
            return
        if flights_used == k + 1:
            return
        for a, b, price in flights:
            if a == city:
                go(b, cost + price, flights_used + 1)

    go(src, 0, 0)
    return -1 if best[0] is None else best[0]

def cheapest_with_stops(n, flights, src, dst, k):
    inf = float("inf")
    price = [inf] * n
    price[src] = 0
    for _ in range(k + 1):
        nxt = price[:]
        for a, b, p in flights:
            if price[a] + p < nxt[b]:
                nxt[b] = price[a] + p
        price = nxt
    return -1 if price[dst] == inf else price[dst]

function cheapestWithStops(n, flights, src, dst, k) {
  let price = new Array(n).fill(Infinity);
  price[src] = 0;
  for (let round = 0; round <= k; round++) {
    const next = [...price];
    for (const [a, b, p] of flights) if (price[a] + p < next[b]) next[b] = price[a] + p;
    price = next;
  }
  return price[dst] === Infinity ? -1 : price[dst];
}

class Solution {
    public int cheapestWithStops(int n, int[][] flights, int src, int dst, int k) {
        long INF = Long.MAX_VALUE / 4;
        long[] price = new long[n];
        Arrays.fill(price, INF);
        price[src] = 0;
        for (int round = 0; round <= k; round++) {
            long[] next = price.clone();
            for (int[] f : flights) if (price[f[0]] + f[2] < next[f[1]]) next[f[1]] = price[f[0]] + f[2];
            price = next;
        }
        return price[dst] >= INF ? -1 : (int) price[dst];
    }
}

int cheapest_with_stops(int n, vector<vector<int>>& flights, int src, int dst, int k) {
    const long long INF = LLONG_MAX / 4;
    vector<long long> price(n, INF);
    price[src] = 0;
    for (int round = 0; round <= k; round++) {
        vector<long long> next = price;
        for (auto& f : flights) if (price[f[0]] + f[2] < next[f[1]]) next[f[1]] = price[f[0]] + f[2];
        price = next;
    }
    return price[dst] >= INF ? -1 : (int) price[dst];
}

def is_clean_palindrome(text):
