        int value = 0;
        for (int step = 0; step < k; step++) {
            int[] top = heap.poll();
            value = top[0];
            if (top[2] + 1 < lists[top[1]].length) heap.add(new int[]{lists[top[1]][top[2] + 1], top[1], top[2] + 1});
        }
