    for u, v, w in roads:
        adjacent[u].append((v, w))
    dist = [None] * n
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == end:
            return d
        for v, w in adjacent[u]:
            nd = d + w
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1

function cheapestRoute(n, roads, start, end) {
  const INF = Infinity;
  const dist = new Array(n).fill(INF);
  const done = new Array(n).fill(false);
  dist[start] = 0;
  for (let round = 0; round < n; round++) {
    let u = -1;
    for (let i = 0; i < n; i++) if (!done[i] && (u === -1 || dist[i] < dist[u])) u = i;
    if (u === -1 || dist[u] === INF) break;
    done[u] = true;
    for (const [from, to, cost] of roads) if (from === u && dist[u] + cost < dist[to]) dist[to] = dist[u] + cost;
  }
  return dist[end] === INF ? -1 : dist[end];
}

class Solution {
    public int cheapestRoute(int n, int[][] roads, int start, int end) {
        List<List<int[]>> adjacent = new ArrayList<>();
        for (int i = 0; i < n; i++) adjacent.add(new ArrayList<>());
        for (int[] r : roads) adjacent.get(r[0]).add(new int[]{r[1], r[2]});
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        heap.add(new long[]{0, start});
        while (!heap.isEmpty()) {
            long[] top = heap.poll();
            int u = (int) top[1];
            if (top[0] > dist[u]) continue;
            if (u == end) return (int) top[0];
            for (int[] edge : adjacent.get(u)) {
                long nd = top[0] + edge[1];
                if (nd < dist[edge[0]]) { dist[edge[0]] = nd; heap.add(new long[]{nd, edge[0]}); }
            }
        }
        return -1;
    }
}

