  let sum = n * (n + 1) / 2;
  for (const x of numbers) sum -= x;
  return sum;
}

class Solution {
    public int findMissing(int[] numbers) {
        long sum = (long) numbers.length * (numbers.length + 1) / 2;
        for (int x : numbers) sum -= x;
        return (int) sum;
    }
}

int find_missing(vector<int>& numbers) {
    long long sum = (long long) numbers.size() * (numbers.size() + 1) / 2;
    for (int x : numbers) sum -= x;
    return (int) sum;
}

def peak_index(heights):
    lo, hi = 0, len(heights) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if heights[mid] < heights[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo

