        if (heights[mid] < heights[mid + 1]) lo = mid + 1; else hi = mid;
    }
    return lo;
}

def count_queens(n):
    cols = []

    def place(row):
        if row == n:
            return 1
        total = 0
        for c in range(n):
            if all(c != cols[r] and abs(c - cols[r]) != row - r for r in range(row)):
                cols.append(c)
                total += place(row + 1)
                cols.pop()
        return total

    return place(0)

def count_queens(n):
    full = (1 << n) - 1

    def place(cols, diag, anti):
        if cols == full:
            return 1
        total = 0
        free = full & ~(cols | diag | anti)
        while free:
            bit = free & -free
            free -= bit
            total += place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1)
        return total

    return place(0, 0, 0)

function countQueens(n) {
  const full = (1 << n) - 1;
  const place = (cols, diag, anti) => {
    if (cols === full) return 1;
    let total = 0;
    let free = full & ~(cols | diag | anti);
    while (free) {
      const bit = free & -free;
      free -= bit;
      total += place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1);
    }
    return total;
  };
  return place(0, 0, 0);
}

class Solution {
    private int place(int cols, int diag, int anti, int full) {
        if (cols == full) return 1;
        int total = 0;
        int free = full & ~(cols | diag | anti);
        while (free != 0) {
            int bit = free & -free;
            free -= bit;
            total += place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1, full);
        }
        return total;
    }

    public int countQueens(int n) {
        return place(0, 0, 0, (1 << n) - 1);
    }
}

static int queens_place(int cols, int diag, int anti, int full) {
    if (cols == full) return 1;
    int total = 0;
    int free_cells = full & ~(cols | diag | anti);
    while (free_cells) {
        int bit = free_cells & -free_cells;
        free_cells -= bit;
        total += queens_place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1, full);
    }
    return total;
}
int count_queens(int n) {
    return queens_place(0, 0, 0, (1 << n) - 1);
}

def has_nearby_duplicate(readings, k):
    for i in range(len(readings)):
        for j in range(i + 1, min(len(readings), i + k + 1)):
            if readings[i] == readings[j]:
                return True
    return False

def has_nearby_duplicate(readings, k):
    last = {}
    for i, x in enumerate(readings):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False

function hasNearbyDuplicate(readings, k) {
  const last = new Map();
  for (let i = 0; i < readings.length; i++) {
    const x = readings[i];
    if (last.has(x) && i - last.get(x) <= k) return true;
    last.set(x, i);
  }
  return false;
}

class Solution {
    public boolean hasNearbyDuplicate(int[] readings, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < readings.length; i++) {
            Integer prev = last.get(readings[i]);
            if (prev != null && i - prev <= k) return true;
            last.put(readings[i], i);
        }
        return false;
    }
}

bool has_nearby_duplicate(vector<int>& readings, int k) {
    unordered_map<int, int> last;
    for (int i = 0; i < (int) readings.size(); i++) {
        auto it = last.find(readings[i]);
        if (it != last.end() && i - it->second <= k) return true;
        last[readings[i]] = i;
    }
    return false;
}

def next_arrangement(nums):
    from itertools import permutations

    arrangements = sorted(set(permutations(nums)))
    index = arrangements.index(tuple(nums))
    return list(arrangements[(index + 1) % len(arrangements)])

def next_arrangement(nums):
    a = list(nums)
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return a

function nextArrangement(nums) {
  const a = [...nums];
  const n = a.length;
  let i = n - 2;
  while (i >= 0 && a[i] >= a[i + 1]) i--;
  if (i >= 0) {
    let j = n - 1;
    while (a[j] <= a[i]) j--;
    [a[i], a[j]] = [a[j], a[i]];
  }
  let lo = i + 1, hi = n - 1;
  while (lo < hi) { [a[lo], a[hi]] = [a[hi], a[lo]]; lo++; hi--; }
  return a;
}

class Solution {
    public int[] nextArrangement(int[] nums) {
        int[] a = nums.clone();
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (a[j] <= a[i]) j--;
            int t = a[i]; a[i] = a[j]; a[j] = t;
        }
        int lo = i + 1, hi = n - 1;
        while (lo < hi) { int t = a[lo]; a[lo] = a[hi]; a[hi] = t; lo++; hi--; }
        return a;
    }
}

vector<int> next_arrangement(vector<int>& nums) {
    vector<int> a = nums;
    int n = (int) a.size();
    int i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i >= 0) {
        int j = n - 1;
        while (a[j] <= a[i]) j--;
        swap(a[i], a[j]);
    }
    reverse(a.begin() + i + 1, a.end());
    return a;
}

def count_no_adjacent_ones(n):
    count = 0
    for mask in range(1 << n):
        if mask & (mask >> 1) == 0:  # no two neighbouring 1 bits
            count += 1
    return count

def count_no_adjacent_ones(n):
    memo = {}

    def go(remaining, last_is_one):
        if remaining == 0:
            return 1
        key = (remaining, last_is_one)
        if key not in memo:
            total = go(remaining - 1, False)
            if not last_is_one:
                total += go(remaining - 1, True)
            memo[key] = total
        return memo[key]

    return go(n, False)

def count_no_adjacent_ones(n):
    ends_zero, ends_one = 1, 1
    for _ in range(n - 1):
        ends_zero, ends_one = ends_zero + ends_one, ends_zero
    return ends_zero + ends_one

function countNoAdjacentOnes(n) {
  let endsZero = 1, endsOne = 1;
  for (let i = 1; i < n; i++) [endsZero, endsOne] = [endsZero + endsOne, endsZero];
  return endsZero + endsOne;
}

class Solution {
    public int countNoAdjacentOnes(int n) {
        int endsZero = 1, endsOne = 1;
        for (int i = 1; i < n; i++) { int z = endsZero + endsOne; endsOne = endsZero; endsZero = z; }
        return endsZero + endsOne;
    }
}

