    for (int i = 1; i < n; i++) { int z = ends_zero + ends_one; ends_one = ends_zero; ends_zero = z; }
    return ends_zero + ends_one;
}

def fence_ways(posts, colors):
    from itertools import product

    count = 0
    for paint in product(range(colors), repeat=posts):
        if all(not (paint[i] == paint[i + 1] == paint[i + 2]) for i in range(posts - 2)):
            count += 1
    return count

def fence_ways(posts, colors):
    memo = {}

    def go(remaining, run):  # run = how many equal posts end the fence so far (1 or 2)
        if remaining == 0:
            return 1
        if (remaining, run) not in memo:
            total = go(remaining - 1, 1) * (colors - 1)  # a different color
            if run == 1:
                total += go(remaining - 1, 2)  # the same color again
            memo[(remaining, run)] = total
        return memo[(remaining, run)]

    return colors * go(posts - 1, 1)

def fence_ways(posts, colors):
    if posts == 1:
        return colors
    same, diff = colors, colors * (colors - 1)
    for _ in range(posts - 2):
        same, diff = diff, (same + diff) * (colors - 1)
    return same + diff

function fenceWays(posts, colors) {
  if (posts === 1) return colors;
  let same = colors, diff = colors * (colors - 1);
  for (let i = 0; i < posts - 2; i++) [same, diff] = [diff, (same + diff) * (colors - 1)];
  return same + diff;
}

class Solution {
    public int fenceWays(int posts, int colors) {
        if (posts == 1) return colors;
        long same = colors, diff = (long) colors * (colors - 1);
        for (int i = 0; i < posts - 2; i++) { long next = (same + diff) * (colors - 1); same = diff; diff = next; }
        return (int) (same + diff);
    }
}

