}

def count_pairs(prices, budget):
    total = 0
    for i in range(len(prices)):
        for j in range(i + 1, len(prices)):
            if prices[i] + prices[j] == budget:
                total += 1
    return total

def count_pairs(prices, budget):
    count = {}
    total = 0
    for p in prices:
        total += count.get(budget - p, 0)
        count[p] = count.get(p, 0) + 1
    return total

function countPairs(prices, budget) {
  const count = new Map();
  let total = 0;
  for (const p of prices) {
    total += count.get(budget - p) || 0;
    count.set(p, (count.get(p) || 0) + 1);
  }
  return total;
}

class Solution {
    public int countPairs(int[] prices, int budget) {
        Map<Integer, Integer> count = new HashMap<>();
        int total = 0;
        for (int p : prices) {
            total += count.getOrDefault(budget - p, 0);
            count.merge(p, 1, Integer::sum);
        }
        return total;
    }
}

int count_pairs(vector<int>& prices, int budget) {
    unordered_map<int, int> count;
    int total = 0;
    for (int p : prices) {
        auto it = count.find(budget - p);
        if (it != count.end()) total += it->second;
        count[p]++;
    }
    return total;
}

def count_palindrome_splits(text):
    def go(start):
        if start == len(text):
            return 1
        total = 0
        for end in range(start + 1, len(text) + 1):
            piece = text[start:end]
            if piece == piece[::-1]:
                total += go(end)
        return total

    return go(0)

def count_palindrome_splits(text):
    n = len(text)
    ways = [1] + [0] * n
    for end in range(1, n + 1):
        for start in range(end):
            piece = text[start:end]
            if piece == piece[::-1]:
                ways[end] += ways[start]
    return ways[n]

function countPalindromeSplits(text) {
  const n = text.length;
  const isPal = (lo, hi) => {
    while (lo < hi) { if (text[lo] !== text[hi]) return false; lo++; hi--; }
    return true;
  };
  const ways = new Array(n + 1).fill(0);
  ways[0] = 1;
  for (let end = 1; end <= n; end++) {
    for (let start = 0; start < end; start++) if (isPal(start, end - 1)) ways[end] += ways[start];
  }
  return ways[n];
}

class Solution {
    private boolean isPal(String text, int lo, int hi) {
        while (lo < hi) { if (text.charAt(lo) != text.charAt(hi)) return false; lo++; hi--; }
        return true;
    }

    public int countPalindromeSplits(String text) {
        int n = text.length();
        int[] ways = new int[n + 1];
        ways[0] = 1;
        for (int end = 1; end <= n; end++) {
            for (int start = 0; start < end; start++) if (isPal(text, start, end - 1)) ways[end] += ways[start];
        }
        return ways[n];
    }
}

static bool is_pal_range(const string& text, int lo, int hi) {
