def can_split_equal(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    sums = [0] * k

    def go(i):
        if i == len(nums):
            return all(s == target for s in sums)
        for g in range(k):
            sums[g] += nums[i]
            found = go(i + 1)
            sums[g] -= nums[i]
            if found:
                return True
        return False

    return go(0)

def can_split_equal(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    n = len(nums)
    if max(nums) > target:
        return False
    partial = [-1] * (1 << n)  # partial[mask] = sum of the group currently being filled (mod target)
    partial[0] = 0
    for mask in range(1 << n):
        if partial[mask] == -1:
            continue
        for i in range(n):
            if not mask & (1 << i) and partial[mask] + nums[i] <= target:
                nxt = mask | (1 << i)
                if partial[nxt] == -1:
                    partial[nxt] = (partial[mask] + nums[i]) % target
    return partial[(1 << n) - 1] == 0

def can_split_equal(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    nums = sorted(nums, reverse=True)
    if nums[0] > target:
        return False
    groups = [0] * k

    def place(i):
        if i == len(nums):
            return True
        tried = set()
        for g in range(k):
            if groups[g] + nums[i] <= target and groups[g] not in tried:
                tried.add(groups[g])
                groups[g] += nums[i]
                if place(i + 1):
                    return True
                groups[g] -= nums[i]
        return False

    return place(0)

function canSplitEqual(nums, k) {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % k !== 0) return false;
  const target = total / k;
  const sorted = [...nums].sort((a, b) => b - a);
  if (sorted[0] > target) return false;
  const groups = new Array(k).fill(0);
  const place = (i) => {
    if (i === sorted.length) return true;
    const tried = new Set();
    for (let g = 0; g < k; g++) {
      if (groups[g] + sorted[i] <= target && !tried.has(groups[g])) {
        tried.add(groups[g]);
        groups[g] += sorted[i];
        if (place(i + 1)) return true;
        groups[g] -= sorted[i];
      }
    }
    return false;
  };
  return place(0);
}

class Solution {
    private int[] sorted;
    private int[] groups;
    private int target;

    private boolean place(int i) {
        if (i == sorted.length) return true;
        Set<Integer> tried = new HashSet<>();
        for (int g = 0; g < groups.length; g++) {
            if (groups[g] + sorted[i] <= target && tried.add(groups[g])) {
                groups[g] += sorted[i];
                if (place(i + 1)) return true;
                groups[g] -= sorted[i];
            }
        }
        return false;
    }

    public boolean canSplitEqual(int[] nums, int k) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        target = total / k;
        sorted = nums.clone();
        Arrays.sort(sorted);
        for (int i = 0, j = sorted.length - 1; i < j; i++, j--) { int t = sorted[i]; sorted[i] = sorted[j]; sorted[j] = t; }
        if (sorted[0] > target) return false;
        groups = new int[k];
        return place(0);
    }
}

static bool split_place(const vector<int>& sorted_nums, vector<int>& groups, int target, size_t i) {
    if (i == sorted_nums.size()) return true;
    set<int> tried;
    for (size_t g = 0; g < groups.size(); g++) {
        if (groups[g] + sorted_nums[i] <= target && !tried.count(groups[g])) {
            tried.insert(groups[g]);
            groups[g] += sorted_nums[i];
            if (split_place(sorted_nums, groups, target, i + 1)) return true;
            groups[g] -= sorted_nums[i];
        }
    }
    return false;
}
bool can_split_equal(vector<int>& nums, int k) {
    int total = 0;
    for (int x : nums) total += x;
    if (total % k != 0) return false;
    int target = total / k;
    vector<int> sorted_nums = nums;
    sort(sorted_nums.begin(), sorted_nums.end(), greater<int>());
    if (sorted_nums[0] > target) return false;
    vector<int> groups(k, 0);
    return split_place(sorted_nums, groups, target, 0);
}

