def max_overlap(talks):
    best = 0
    for start, _ in talks:
        running = sum(1 for s, e in talks if s <= start < e)
        best = max(best, running)
    return best

def max_overlap(talks):
    starts = sorted(t[0] for t in talks)
    ends = sorted(t[1] for t in talks)
    i = j = running = best = 0
    while i < len(starts):
        if starts[i] < ends[j]:
            running += 1
            i += 1
            best = max(best, running)
        else:
            running -= 1
            j += 1
    return best

function maxOverlap(talks) {
  const starts = talks.map((t) => t[0]).sort((a, b) => a - b);
  const ends = talks.map((t) => t[1]).sort((a, b) => a - b);
  let i = 0, j = 0, running = 0, best = 0;
  while (i < starts.length) {
    if (starts[i] < ends[j]) { running++; i++; best = Math.max(best, running); }
    else { running--; j++; }
  }
  return best;
}

class Solution {
    public int maxOverlap(int[][] talks) {
        int n = talks.length;
        int[] starts = new int[n], ends = new int[n];
        for (int k = 0; k < n; k++) { starts[k] = talks[k][0]; ends[k] = talks[k][1]; }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int i = 0, j = 0, running = 0, best = 0;
        while (i < n) {
            if (starts[i] < ends[j]) { running++; i++; best = Math.max(best, running); }
            else { running--; j++; }
        }
        return best;
    }
}

int max_overlap(vector<vector<int>>& talks) {
    vector<int> starts, ends;
    for (auto& t : talks) { starts.push_back(t[0]); ends.push_back(t[1]); }
    sort(starts.begin(), starts.end());
    sort(ends.begin(), ends.end());
    size_t i = 0, j = 0;
    int running = 0, best = 0;
    while (i < starts.size()) {
        if (starts[i] < ends[j]) { running++; i++; best = max(best, running); }
        else { running--; j++; }
    }
    return best;
}

def eval_postfix(expr):
    # repeatedly replace the first 'a b op' triple with its value
    tokens = expr.split(" ")
    while len(tokens) > 1:
        for i in range(2, len(tokens)):
            if tokens[i] in ("+", "-", "*"):
                a, b = int(tokens[i - 2]), int(tokens[i - 1])
                value = a + b if tokens[i] == "+" else a - b if tokens[i] == "-" else a * b
                tokens[i - 2:i + 1] = [str(value)]
                break
    return int(tokens[0])

def eval_postfix(expr):
    stack = []
    for token in expr.split(" "):
        if token in ("+", "-", "*"):
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b if token == "+" else a - b if token == "-" else a * b)
        else:
            stack.append(int(token))
    return stack[0]

function evalPostfix(expr) {
  const stack = [];
  for (const token of expr.split(" ")) {
    if (token === "+" || token === "-" || token === "*") {
      const b = stack.pop();
      const a = stack.pop();
      stack.push(token === "+" ? a + b : token === "-" ? a - b : a * b);
    } else {
      stack.push(parseInt(token, 10));
    }
  }
  return stack[0];
}

class Solution {
    public int evalPostfix(String expr) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String token : expr.split(" ")) {
            if (token.equals("+") || token.equals("-") || token.equals("*")) {
                int b = stack.pop();
                int a = stack.pop();
                stack.push(token.equals("+") ? a + b : token.equals("-") ? a - b : a * b);
            } else {
                stack.push(Integer.parseInt(token));
            }
        }
        return stack.pop();
    }
}

int eval_postfix(string expr) {
    vector<int> stack;
    istringstream in(expr);
    string token;
    while (in >> token) {
        if (token == "+" || token == "-" || token == "*") {
            int b = stack.back(); stack.pop_back();
            int a = stack.back(); stack.pop_back();
            stack.push_back(token == "+" ? a + b : token == "-" ? a - b : a * b);
        } else {
            stack.push_back(stoi(token));
        }
    }
    return stack.back();
}

