def minutes_to_rot(grid):
    from collections import deque

    rows, cols = len(grid), len(grid[0])
    cells = [row[:] for row in grid]
    queue = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if cells[r][c] == 2:
                queue.append((r, c, 0))
            elif cells[r][c] == 1:
                fresh += 1
    minutes = 0
    while queue:
        r, c, t = queue.popleft()
        minutes = max(minutes, t)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and cells[nr][nc] == 1:
                cells[nr][nc] = 2
                fresh -= 1
