    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) counts.merge(x, 1, Integer::sum);
        List<Integer> values = new ArrayList<>(counts.keySet());
        values.sort((a, b) -> counts.get(b).equals(counts.get(a)) ? Integer.compare(a, b) : Integer.compare(counts.get(b), counts.get(a)));
        int[] result = new int[k];
        for (int i = 0; i < k; i++) result[i] = values.get(i);
        return result;
    }
}

