class Solution {
    public int sumOfTopK(int[] scores, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int s : scores) {
            heap.add(s);
            if (heap.size() > k) heap.poll();
        }
        int sum = 0;
        for (int s : heap) sum += s;
        return sum;
    }
}

int sum_of_top_k(vector<int>& scores, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int s : scores) {
        heap.push(s);
        if ((int) heap.size() > k) heap.pop();
    }
    int sum = 0;
    while (!heap.empty()) { sum += heap.top(); heap.pop(); }
    return sum;
}

