def tree_diameter(root):
    def height(node):
        return 0 if node is None else 1 + max(height(node.left), height(node.right))

    best = 0

    def visit(node):
        nonlocal best
        if node is None:
            return
        best = max(best, height(node.left) + height(node.right))
        visit(node.left)
        visit(node.right)

    visit(root)
    return best

