def window_max_total(temps, k):
    from collections import deque

    window = deque()
    total = 0
    for i, x in enumerate(temps):
        while window and temps[window[-1]] <= x:
            window.pop()
        window.append(i)
        if window[0] <= i - k:
            window.popleft()
        if i >= k - 1:
            total += temps[window[0]]
    return total

function windowMaxTotal(temps, k) {
  const window = [];
  let head = 0, total = 0;
  for (let i = 0; i < temps.length; i++) {
    while (window.length > head && temps[window[window.length - 1]] <= temps[i]) window.pop();
    window.push(i);
    if (window[head] <= i - k) head++;
    if (i >= k - 1) total += temps[window[head]];
  }
  return total;
}

class Solution {
    public int windowMaxTotal(int[] temps, int k) {
        Deque<Integer> window = new ArrayDeque<>();
        long total = 0;
        for (int i = 0; i < temps.length; i++) {
            while (!window.isEmpty() && temps[window.peekLast()] <= temps[i]) window.pollLast();
            window.addLast(i);
            if (window.peekFirst() <= i - k) window.pollFirst();
            if (i >= k - 1) total += temps[window.peekFirst()];
        }
        return (int) total;
    }
}

int window_max_total(vector<int>& temps, int k) {
    deque<int> window;
    long long total = 0;
    for (int i = 0; i < (int) temps.size(); i++) {
        while (!window.empty() && temps[window.back()] <= temps[i]) window.pop_back();
        window.push_back(i);
        if (window.front() <= i - k) window.pop_front();
        if (i >= k - 1) total += temps[window.front()];
    }
    return (int) total;
}

