function followsPattern(pattern, sentence) {
  const words = sentence.split(" ");
  if (words.length !== pattern.length) return false;
  const letterToWord = new Map(), wordToLetter = new Map();
  for (let i = 0; i < pattern.length; i++) {
    const letter = pattern[i], word = words[i];
    if (letterToWord.has(letter) && letterToWord.get(letter) !== word) return false;
    if (wordToLetter.has(word) && wordToLetter.get(word) !== letter) return false;
    letterToWord.set(letter, word);
    wordToLetter.set(word, letter);
  }
  return true;
}

class Solution {
    public boolean followsPattern(String pattern, String sentence) {
        String[] words = sentence.split(" ");
        if (words.length != pattern.length()) return false;
        Map<Character, String> letterToWord = new HashMap<>();
        Map<String, Character> wordToLetter = new HashMap<>();
        for (int i = 0; i < pattern.length(); i++) {
            char letter = pattern.charAt(i);
            String word = words[i];
            if (letterToWord.containsKey(letter) && !letterToWord.get(letter).equals(word)) return false;
            if (wordToLetter.containsKey(word) && wordToLetter.get(word) != letter) return false;
            letterToWord.put(letter, word);
            wordToLetter.put(word, letter);
        }
        return true;
    }
}

bool follows_pattern(string pattern, string sentence) {
    vector<string> words;
    istringstream in(sentence);
    string w;
    while (in >> w) words.push_back(w);
    if (words.size() != pattern.size()) return false;
    map<char, string> letter_to_word;
    map<string, char> word_to_letter;
    for (size_t i = 0; i < pattern.size(); i++) {
        char letter = pattern[i];
        if (letter_to_word.count(letter) && letter_to_word[letter] != words[i]) return false;
        if (word_to_letter.count(words[i]) && word_to_letter[words[i]] != letter) return false;
        letter_to_word[letter] = words[i];
        word_to_letter[words[i]] = letter;
    }
    return true;
}
